import {MORE_COURSE,morePapers} from './continuation-content.e518df4e9bd6.js';
const R=String.raw;
const eq=s=>`<div class="math">\\(${s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}\\)</div>`;
const b=(s,k=1,cls='lead')=>`<div class="b ${cls}" data-at="${k}">${s}</div>`;
const list=items=>`<ul class="list">${items.map((x,i)=>`<li class="b" data-at="${i+1}">${x}</li>`).join('')}</ul>`;
const tok=(words,focus=-1)=>`<div class="tokens">${words.map((w,i)=>`<span class="token ${i===focus?'focus':''}">${w}</span>`).join('')}</div>`;
const paper={ngram:['Chen & Goodman · smoothing','https://aclanthology.org/P96-1041/'],neural:['Bengio et al. · neural probabilistic LM (2003)','https://www.jmlr.org/papers/v3/bengio03a.html'],rnn:['Elman · Finding Structure in Time (1990)','https://doi.org/10.1207/s15516709cog1402_1'],lstm:['Hochreiter & Schmidhuber · LSTM (1997)','https://doi.org/10.1162/neco.1997.9.8.1735'],gru:['Cho et al. · RNN encoder–decoder (2014)','https://aclanthology.org/D14-1179/'],seq:['Sutskever et al. · Sequence to Sequence Learning (2014)','https://arxiv.org/abs/1409.3215'],attn:['Bahdanau et al. · joint alignment and translation (2015)','https://arxiv.org/abs/1409.0473'],transformer:['Vaswani et al. · Attention Is All You Need (2017)','https://arxiv.org/abs/1706.03762'],bert:['Devlin et al. · BERT (2019)','https://aclanthology.org/N19-1423/']};
const src=(key,slides)=>`<a href="${paper[key][1]}" target="_blank" rel="noopener">${paper[key][0]}</a> · Lecture slides ${slides}`;
const text=(sec,title,html,notes='',source='')=>({sec,title,kind:'text',html,notes,source});
const scene=(sec,title,name,notes='',source='')=>({sec,title,kind:'scene',scene:name,notes,source});
const cover=(part,title,subtitle)=>({sec:'Start',title,kind:'cover',subtitle,notes:`This is Part ${part}, a study companion to Shamsuddeen Muhammad’s lecture. Take the time to work through each mechanism. Numeric visualisations are computed teaching examples, not pretrained-model outputs.`,source:'Based on Shamsuddeen Muhammad · From Counting Words to Pretrained Transformers · 24 Nov 2026'});
const quiz=(sec,title,prompt,answer,notes='')=>text(sec,title,`<div class="statement">${prompt}</div>${b(answer,1,'answer')}`,notes||answer);
const end=(part,title,items,next)=>text('Review',title,list(items)+(next?b(`<a href="../part-${next}/">Continue to Part ${next}</a>`,items.length+1,'sub'):''),'Pause before the next deck. Explain the mechanism in your own words rather than memorising a diagram.');
Object.assign(paper,morePapers);
export const COURSE=[
{id:1,title:'Language models and n-grams',short:'Probabilities & counts',subtitle:'What does it mean to predict the next token?',slides:[
cover(1,'Language models and n-grams','Probabilities, counting, smoothing—and what the counts cannot tell us'),
text('Probability','A next-token prediction',tok(['Transformers','are','…'])+b('A language model returns a distribution over possible next tokens.')+b('“great” and “powerful” can both be plausible. The probabilities must sum to one.',2,'sub'),'The lecture opens with next-word probabilities. We use token because modern models may work with subwords or characters. No pretrained probabilities are shown here.','Lecture slide 4'),
scene('Probability','The chain rule','chain-rule','The chain rule factors a joint probability into conditional probabilities without an independence assumption. Include the end token when modelling variable-length complete sequences.','Lecture slide 4'),
text('Probability','Prediction, likelihood and generation',list(['Prediction: compute a distribution for the next token.','Likelihood: score the tokens that actually occurred.','Generation: choose a token, append it, and repeat.']),'Choosing the most likely token is greedy decoding; sampling draws from the distribution. Neither choice changes what the language model distribution represents.','Lecture slide 4'),
text('N-grams','A short context approximation',eq(R`P(w_t\mid w_{<t})\approx P(w_t\mid w_{t-n+1:t-1})`)+b('A bigram uses one previous token; a trigram uses two.')+b('This is the Markov assumption. It is a model choice, not the chain rule.',2,'sub'),'The term n-gram includes the token being predicted. A neural fixed-context model often instead describes the number of preceding tokens. Keep those conventions separate.','Lecture slide 8'),
scene('N-grams','The context window','ngram-window','Choose different n values. Explain why “cabinet” is not the grammatical subject of “are”. An n-gram has no mechanism to reach outside its chosen context.','Lecture slide 11'),
scene('N-grams','A model built from actual counts','counts','The corpus is visible in full. Start markers are contexts; the seven-token prediction vocabulary includes the end marker and excludes the start marker.','Lecture slides 8–9 · Computed three-sentence corpus'),
text('N-grams','Scoring a complete sentence',eq(R`P(\text{I like NLP </s>})=1\times\frac{2}{3}\times\frac{1}{2}\times1=\frac13`)+b('Each factor comes from the same three-sentence corpus.')+b('The end-token factor matters: P(</s> | NLP) = 2/2.',2,'sub'),'The start marker is supplied, not predicted. Given it, P(I)=1. Given I, like occurs twice among three transitions. Given like, NLP occurs once among two.','Lecture slide 9'),
text('Smoothing','An unseen phrase gets zero',tok(['I','like','learning'],2)+b('The corpus never contains “like learning”. Its maximum-likelihood probability is zero.')+b('One zero factor makes the whole sentence probability zero.',2,'statement'),'The phrase is plausible English, but this exact transition never occurs in our tiny corpus. Smoothing gives coverage, not grammatical understanding.',src('ngram','10')),
scene('Smoothing','Smoothing redistributes probability','smoothing','The add-α distribution uses all seven prediction symbols. At α=1, P(learning | like)=1/(2+7)=1/9. At α=0, P(learning | like)=0. Move the slider and check that the sum remains one.',src('ngram','10')),
text('Smoothing','Backoff, interpolation and continuation',list(['Backoff uses a lower-order model when the higher-order context is unreliable.','Interpolation combines distributions from several context lengths.','Kneser–Ney uses continuation diversity in its lower-order distribution.']),'Do not present continuation probability as simply unigram frequency. A word seen after many distinct histories can be a better continuation than a frequent word restricted to one phrase.',src('ngram','7, 10')),
text('Evaluation','Perplexity measures average surprise',eq(R`\mathrm{PPL}=\exp\!\left(-\frac1T\sum_{t=1}^{T}\log P(w_t\mid w_{<t})\right)`)+b('Example: probabilities 1/2, 1/4, 1/4 give PPL = 32¹ᐟ³ ≈ 3.175.')+b('Compare models on the same held-out text and tokenisation.',2,'sub'),'Use natural logs with exp, or log base two with 2 to that power. Padding and start tokens are usually excluded. Perplexity is not a factuality or reasoning benchmark.','Lecture slide 4 · Worked held-out example'),
text('Limits','The cost of a bigger context',`<div class="two"><div><div class="big-number">Vⁿ</div><p>possible n-grams</p></div><div>${b('With V = 50,000, there are 1.25 × 10¹⁴ possible trigrams.')} ${b('Most never occur. Similar words remain separate symbols.',2)}</div></div>`,'This counts possible strings, not the number of entries an implementation must store. Sparse count tables store observed events. Large n still increases sparsity and storage pressure.','Lecture slide 11'),
quiz('Review','Check your understanding','If “dog” is new but “cat” is common, does add-one smoothing learn that they are similar?','No. It gives unseen events probability, but does not learn a shared representation of word meaning.'),
end(1,'What carries forward',['The chain rule defines the probability task.','N-grams approximate context and estimate probabilities from counts.','Neural embeddings will replace unrelated symbols with learnable vectors.'],2)
]},
{id:2,title:'Neural LMs, RNNs, LSTM and GRU',short:'Neural models & memory',subtitle:'What exactly moves through a recurrent network?',slides:[
cover(2,'Neural language models and memory','A close look at the hidden state, gradient paths, and gated cells'),
text('Embeddings','Learning a representation',list(['An embedding table maps token IDs to dense vectors.','Training updates the embeddings and prediction network together.','Shared parameters can transfer statistical evidence between similar contexts.']),'Embedding similarity is learned from the training objective, not guaranteed to match human similarity in every case. An embedding is a vector lookup; it is not a contextual hidden state.',src('neural','12–14')),
scene('Embeddings','A fixed-window neural language model','neural-lm','Follow token IDs through embeddings, concatenation, a hidden layer, vocabulary projection and softmax. Bengio’s model can also have direct connections; this is the central feed-forward path.',src('neural','13–14')),
text('Embeddings','Shapes through the neural predictor',eq(R`E\in\mathbb R^{V\times d},\quad x=[e_{t-3};e_{t-2};e_{t-1}]\in\mathbb R^{3d}`)+b(eq(R`h=\tanh(Wx+b),\qquad p=\operatorname{softmax}(Uh+c)`))+b('A fixed context length does not require a fixed sentence length. Slide the window across the sentence.',2,'sub'),'This clarifies a simplification in the lecture. Short prefixes can be padded with start symbols; long sentences supply many fixed-window training cases. The limitation is visibility outside the window, not inability to process a long sentence.',src('neural','13–15')),
text('Recurrence','A state carries context forward',eq(R`h_t=\tanh(W_xx_t+W_hh_{t-1}+b)`)+b('The current token and previous state produce the next state.')+b('The same learned matrices are reused at every time step.',2,'statement'),'Shared weights allow arbitrary sequence lengths in principle. The fixed-dimensional state and training dynamics still limit effective memory.',src('rnn','16–17')),
scene('Recurrence','Inside one RNN cell','rnn-cell','Distinguish input embedding dimension d_x, hidden dimension d_h and vocabulary size V. The recurrent cell produces h_t; a separate output head produces next-token probabilities.',src('rnn','16–17')),
scene('Recurrence','Unrolling the same cell','rnn-unroll','Each drawn cell is the same function with shared weights. Unrolling visualises computation over time, not separate learned networks per word.',src('rnn','17')),
scene('Recurrence','A complete numeric RNN pass','rnn-numeric','All numbers are recomputed in JavaScript from the stated scalar weights. This is an executable teaching model, not an output from a trained language model.','Computed scalar RNN · Wₓ = 0.6, Wₕ = 0.8, b = 0'),
text('Learning','Backpropagation through time',eq(R`\mathcal L=-\sum_t\log P(w_{t+1}\mid h_t)`)+b('Unroll the computation and propagate gradients backwards through its time steps.')+b('Every occurrence of a shared weight contributes to that same parameter’s gradient.',2,'sub'),'Teacher forcing supplies observed input tokens during next-token training. Truncated BPTT limits the number of steps through which the gradient is propagated; it does not change the recurrence itself.','Lecture slides 18–19'),
scene('Learning','Why a gradient can shrink or explode','gradient','The derivative of a recurrent transition includes both recurrent weights and nonlinearities. It is not universally below one. The teaching scalar multiplier isolates the effect of a long product.','Lecture slides 18–19 · Computed teaching factors'),
text('Gates','A gated memory path',list(['A gate is a vector of values between 0 and 1.','Element-wise multiplication controls each coordinate separately.','An additive carry path can preserve information and improve gradient flow.']),'Sigmoid gates are differentiable, so training learns their settings. Gates do not make memory perfect or guarantee non-vanishing gradients.',src('lstm','20–21')),
scene('Gates','LSTM: the complete state update','lstm','Walk through all six operations before moving the forget-gate slider. All gates depend on x_t and h_(t−1); c_(t−1) follows the upper memory path. The diagram uses a modern standard LSTM formulation, not every historical variant.',src('lstm','20–21')),
text('Gates','LSTM equations and tensor shapes',eq(R`[f_t,i_t,o_t]=\sigma(W[x_t;h_{t-1}]+b),\quad g_t=\tanh(W_g[x_t;h_{t-1}]+b_g)`)+b(eq(R`c_t=f_t\odot c_{t-1}+i_t\odot g_t`))+b(eq(R`h_t=o_t\odot\tanh(c_t)`),2)+b('All four gate/candidate vectors, c and h have hidden width dₕ.',3,'sub'),'The concatenated W notation abbreviates three separate learned affine gate transformations. Candidate parameters are distinct. ⊙ denotes element-wise multiplication, not a matrix dot product.',src('lstm','21')),
text('Gates','The carry path and its limits',eq(R`\left.\frac{\partial c_t}{\partial c_{t-1}}\right|_{\text{direct path}}=f_t`)+b('If the forget gate stays near 1, the direct memory path changes little.')+b('The full derivative also includes dependencies through the gates and hidden states.',2,'sub'),'Avoid the claim that LSTM gradients cannot vanish. This is a direct-path intuition, not the entire Jacobian. Forget gates can also intentionally erase information.',src('lstm','20–21')),
scene('Gates','GRU: reset, candidate and update','gru','Our convention makes z the new-candidate fraction. In Cho et al. z commonly denotes old-state retention. Both are equivalent after replacing z with 1−z. Framework implementations can also place reset multiplication differently.',src('gru','20–22')),
text('Gates','GRU equations: a stated convention',eq(R`r_t=\sigma(W_rx_t+U_rh_{t-1}+b_r),\quad z_t=\sigma(W_zx_t+U_zh_{t-1}+b_z)`)+b(eq(R`\widetilde h_t=\tanh(W_xx_t+U_h(r_t\odot h_{t-1})+b)`))+b(eq(R`h_t=(1-z_t)\odot h_{t-1}+z_t\odot\widetilde h_t`),2)+b('Here z means “write new”. Always check the author’s convention.',3,'sub'),'The reset gate acts inside candidate computation. It does not directly erase the carry term. This simple formulation is common in teaching; PyTorch uses a reset-after arrangement for its hidden candidate affine path.',src('gru','21')),
text('Comparison','LSTM and GRU',`<table class="table"><thead><tr><th></th><th>LSTM</th><th>GRU</th></tr></thead><tbody><tr><td>States</td><td>cell c and hidden h</td><td>hidden h</td></tr><tr><td>Affine gate/candidate groups</td><td>4</td><td>3</td></tr><tr><td>Direct state path</td><td>cell carry + write</td><td>old/new hidden mixture</td></tr></tbody></table>${b('At equal input/hidden widths, a standard GRU has fewer parameters. Accuracy and speed depend on the task and implementation.',1,'sub')}`,'Do not claim GRU is universally faster or more accurate. The lecture compares a small set of music/speech tasks; that does not establish a general rule for language modelling.',src('gru','22')),
quiz('Review','A reset-gate question','If r = 0 in our GRU, does hₜ necessarily become zero?','No. The candidate ignores the reset hidden input, but still sees xₜ; the direct carry term can also remain nonzero.'),
text('Applications','The same recurrence can serve different tasks',list(['Tagging uses an output head at each input position.','Classification can use a pooled or final representation.','Translation adds a decoder so output length and order can differ.']),'A recurrent architecture is not inherently restricted to one output per input. That restriction belongs to a simple aligned tagging setup. A decoder can continue for any output length.','Lecture slide 23'),
end(2,'A state is not the whole architecture',['Embeddings encode tokens; recurrence updates contextual state.','LSTM and GRU control memory through learned gates.','An encoder and a decoder can use these cells for a sequence-to-sequence task.'],3)
]},
{id:3,title:'Encoder–decoder models and attention',short:'Seq2seq & attention',subtitle:'How does a decoder retrieve the right source information?',slides:[
cover(3,'Encoder–decoder models and attention','Different lengths, changing context, and a route around the bottleneck'),
text('Seq2seq','Output length and order can change',`<div class="two"><div><h2>Source</h2>${tok(['the','red','car'])}</div><div><h2>Target</h2>${tok(['la','voiture','rouge'])}</div></div>${b('Translation predicts a target sequence, not a label aligned to each source position.',1,'sub')}`,'Word-level examples are used for clarity. Actual tokenisers may split these strings differently. The end marker adds an extra target prediction beyond the three displayed words.',src('seq','24–25')),
scene('Seq2seq','The encoder and decoder at work','seq2seq','Follow the source encoder, context vector, start token, target predictions and end token. Switch training/generation input after the flow is visible.',src('seq','26–27')),
text('Seq2seq','Teacher forcing during training',tok(['&lt;s&gt;','la','voiture','rouge'])+b('Decoder inputs: the true previous target tokens.')+b('Prediction targets: la, voiture, rouge, </s>.',2)+b('The loss compares each next-token distribution with the observed target.',3,'sub'),'Teacher forcing is a training arrangement. At inference the model does not receive future gold targets. Recurrent decoders still have sequential hidden-state dependencies during teacher-forced training.','Lecture slides 26–27 · Training clarification'),
text('Seq2seq','Generation uses its own prefix',list(['Start with the source encoding and a start token.','Predict or sample the next target token.','Append that chosen token and continue until an end or length limit.']),'A wrong early prediction can change later decoder inputs. Exposure bias describes a training–generation mismatch; the deck does not claim a particular remedy solves it.',src('seq','26–27')),
scene('Bottleneck','One vector for a growing source','bottleneck','The course’s equal-values-per-word analogy is only a heuristic. We retain the useful capacity intuition while avoiding a literal per-word memory quota.',src('attn','28–31')),
text('Bottleneck','Long inputs expose the difficulty',list(['The final state must preserve details useful for every target position.','Early source evidence reaches that state through many recurrent transitions.','Source reversal helped some early seq2seq systems, but did not give the decoder direct access to all states.']),'Do not reproduce approximate BLEU numbers as a newly measured experiment. Bahdanau et al. Figure 2 is the primary source for length-dependent performance. Attention helps access source states; it does not guarantee perfect long-context performance.',src('attn','30–31')),
text('Attention','A separate context for each target step',eq(R`e_{t,i}=a(s_{t-1},h_i),\quad\alpha_{t,i}=\operatorname{softmax}_i(e_{t,i})`)+b(eq(R`c_t=\sum_i\alpha_{t,i}h_i`))+b('The decoder can read every encoder state instead of only the final one.',2,'statement'),'The context vector is still fixed-dimensional at each step, but it is recomputed from the whole encoder memory. The bottleneck is bypassed through repeated selective access, not by eliminating vectors.',src('attn','32–33')),
scene('Attention','Scores, softmax and a weighted sum','cross-attention','The example computes dot products for transparent arithmetic. Original Bahdanau attention learns an additive compatibility network. Every shown number is derived from chosen inputs.',src('attn','34')),
text('Attention','Additive and dot-product scoring',`<div class="two"><div><h2>Additive compatibility</h2><div class="math small">${R`\(e_{t,i}=v^\top\tanh(W_ss_{t-1}+W_hh_i)\)`}</div><p>A small learned network compares states.</p></div><div><h2>Dot product</h2><div class="math">${R`\(e_{t,i}=s^\top h_i\)`}</div><p>Our numeric example uses matching vector widths.</p></div></div>${b('Both produce scores; softmax and weighted averaging follow.',1,'sub')}`,'Do not identify all attention with dot-product attention. Compatibility functions differ; Transformer attention uses learned Q/K projections and scaled dot products.',src('attn','32–34')),
scene('Attention','Soft alignment can reorder a translation','alignment','These weights come from row-softmax of stated teaching scores, not an extracted translation model. An attention heatmap can show routing, but does not by itself establish causal explanation.',src('attn','33–34')),
quiz('Attention','A weighted-sum question','Three source states get weights 0.2, 0.3 and 0.5. Does the model select only the third state?','No. It mixes all three; the third contributes most. Soft attention is not an argmax selection.'),
scene('Scaling','Attention around an RNN still has recurrence','parallel','The animation separates recurrent state construction from the attention read. Adding cross-attention does not remove the encoder/decoder recurrent dependency chain.','Lecture slide 35'),
text('Scaling','What changed—and what did not',list(['Changed: the decoder can retrieve a different source mixture at each target step.','Unchanged: recurrent hidden states still depend on preceding recurrent states.','Next: self-attention will replace recurrent sequence mixing inside the Transformer.']),'Some attention computations can be batched, but a standard RNN’s recurrence remains sequential. Avoid saying the GPU sits entirely idle or that no parallelism is possible anywhere.',src('attn','35')),
end(3,'The source stays accessible',['An encoder–decoder separates source reading from target writing.','Attention recomputes context from all source states.','The Transformer will build contextual states without a recurrent chain.'],4)
]},
{id:4,title:'The Transformer',short:'Transformer architecture',subtitle:'Queries, keys, values—and the complete encoder–decoder',slides:[
cover(4,'The Transformer','A deep architectural walkthrough, from one attention row to the whole model'),
text('Overview','What self-attention replaces',list(['Token vectors exchange information through attention rather than recurrent state updates.','Position information must enter the representation or attention mechanism.','Known positions can be computed in parallel within each layer.']),'The original Transformer uses sinusoidal positional encodings. Later families use learned or relative/rotary approaches. The main deck follows the 2017 architecture and labels later variants.',src('transformer','36–40')),
scene('Overview','The complete encoder–decoder map','transformer-map','This is a simplified block map. Later slides open self-attention, multi-head combination, residuals, FFN, masks and cross-attention. Six stacked blocks per side is the original base configuration, not a universal model size.',src('transformer','37')),
text('Input','Token vectors need position information',eq(R`X_t=\operatorname{Embedding}(w_t)+\operatorname{Position}(t)`)+b('Without a position signal, self-attention alone does not encode the input order.')+b('“dog bites man” and “man bites dog” contain the same token set.',2,'sub'),'Pure self-attention without positional information is permutation-equivariant. A pooled set representation can be invariant. Do not confuse the two. Causal masks also provide structural information but are not the original positional encoding.',src('transformer','36–38')),
scene('Q · K · V','Three projections of the token representation','qkv','The tiny model has three tokens and d_k=d_v=2. Projection values are chosen, not trained; the matrix products are real. All matrices are printed so the calculation is reproducible.',src('transformer','38')),
text('Q · K · V','What Q, K and V do',list(['Query: what this position is looking for.','Key: what each available position can be matched on.','Value: the information to mix after weighting.']),'This is an intuition for learned linear projections. They are not human questions, labels or dictionary meanings. In self-attention they are all computed from one sequence.',src('transformer','38')),
scene('Attention','One attention row, calculated completely','attention-math','Select token 1, 2 or 3. Then change full attention to causal attention. Observe that future positions get zero weight only after the scores are masked before softmax.',src('transformer','38–39')),
text('Attention','The attention matrix has a precise meaning',eq(R`A=\operatorname{softmax}_{\mathrm{row}}\!\left(\frac{QK^\top}{\sqrt{d_k}}+M\right),\qquad Z=AV`)+b('Q and K have shape T × dₖ; A has shape T × T; Z has shape T × dᵥ.')+b('Equivalent implementation: scale QKᵀ, then add a 0/−∞ mask before softmax.',2,'sub'),'The mask M contains 0 for allowed connections and −∞ for blocked ones. Add it to the scaled scores before softmax. Row-wise normalisation is over key positions, not query positions.',src('transformer','38')),
scene('Attention','Causal visibility and target shifting','mask','Each causal row can attend to its own supplied input token. Because targets are shifted, that token is not the answer being predicted. Bidirectional masked-LM inputs are constructed by hiding selected tokens.',src('transformer','41')),
scene('Attention','Multi-head attention','heads','Each head uses distinct learned projections. Head count does not mean every head is guaranteed to learn a different interpretable linguistic function.',src('transformer','37–38')),
scene('Blocks','An encoder block, opened up','encoder-block','This follows post-norm as in the original architecture. In pre-norm, norm is applied before the sublayer and the residual bypass stays outside that norm. Both retain compatible outer tensor dimensions.',src('transformer','37')),
scene('Blocks','The position-wise feed-forward network','ffn','The FFN transforms features per token. It does not attend across time. The original base Transformer uses d_model=512 and d_ff=2048, with ReLU; modern models often use gated alternatives.',src('transformer','37')),
text('Blocks','Residuals and layer normalisation',eq(R`Y=\operatorname{LayerNorm}(X+\operatorname{Sublayer}(X))`)+b('The residual addition requires matching shapes.')+b('LayerNorm normalises feature coordinates within each token, using learned scale and bias.',2)+b('It does not average different tokens into one representation.',3,'sub'),'For each token vector, compute mean and variance over its feature dimension. Add epsilon for numerical stability. This differs from BatchNorm, which uses a different set of axes/statistics.',src('transformer','37')),
scene('Decoder','Where cross-attention gets its inputs','cross-qkv','For cross-attention the decoder-side representations produce Q. Encoder memory produces K and V. The output sequence length follows the query sequence. During translation, full source context is available.',src('transformer','37')),
text('Decoder','Three sublayers in each decoder block',list(['Masked self-attention reads the permitted target prefix.','Cross-attention reads the encoder memory.','A position-wise FFN transforms the resulting target vectors.']),'Each sublayer is surrounded by its own residual addition and layer normalisation in the original architecture. Cross-attention is not present in a standard decoder-only GPT block.',src('transformer','37')),
scene('Decoder','The full model with the pieces connected','transformer-map','Revisit the map with the detailed mechanisms in mind. Name where Q, K and V come from at each attention sublayer. The source padding mask and causal target mask serve different purposes.',src('transformer','37')),
scene('Training & generation','A causal model generates one token at a time','generation','The sequence is predetermined for illustration. No model has generated these strings. This scene teaches dependency order, not model quality.',src('transformer','41')),
text('Training & generation','Parallel training versus sequential generation',`<div class="two"><div><h2>Teacher-forced training</h2><p>All input tokens are known.</p><p>The causal mask blocks future information.</p><p>Score all shifted targets together.</p></div><div><h2>Autoregressive generation</h2><p>Future tokens are unknown.</p><p>Choose the next token, append it, continue.</p><p>A KV cache can reuse previous keys and values.</p></div></div>`,'KV caching saves recomputation of past key/value projections; it does not remove the dependence on newly chosen tokens. Efficient kernels affect implementation cost without changing the basic attention definition.',src('transformer','35–41')),
text('Families','Three Transformer families',`<table class="table"><thead><tr><th>Family</th><th>Visibility / objective</th><th>Examples</th></tr></thead><tbody><tr><td>Encoder-only</td><td>Bidirectional context; masked-token training</td><td>BERT, RoBERTa</td></tr><tr><td>Decoder-only</td><td>Causal context; next-token training</td><td>GPT, Llama</td></tr><tr><td>Encoder–decoder</td><td>Source context + target prefix</td><td>T5, BART</td></tr></tbody></table>${b('These are architectural/training patterns, not exclusive lists of possible tasks.',1,'sub')}`,'BERT is trained with masked language modelling and, in its original form, next-sentence prediction. Encoder–decoder models can use denoising or supervised sequence tasks. Avoid implying all pretraining is identical.',src('bert','41')),
text('Limits','What remains expensive',list(['A dense attention head has T × T query–key interactions.','Going from 1,000 to 10,000 tokens gives 100× as many score entries.','Compute, memory, data and context limits still depend on the architecture and implementation.']),'Standard dense attention has quadratic sequence interactions. FlashAttention reduces memory traffic/materialisation and can avoid storing the full score matrix; it does not make dense attention arithmetic linear in T. The lecture’s context examples are historical, not universal modern limits.',src('transformer','40')),
quiz('Review','Trace one complete prediction','At a decoder cross-attention layer, where do Q, K and V come from?','Q comes from the decoder. K and V come from the encoder memory. The final vocabulary head then predicts a target token.'),
end(4,'What you should now be able to explain',['Follow a token through embeddings, attention, residuals, FFN and the output head.','Distinguish self-attention, causal attention and cross-attention.','Explain why parallel training does not make autoregressive generation fully parallel.'],5)
]}
];
export {paper};

COURSE.push(...MORE_COURSE);
